package com.clavis.reader;
import android.graphics.*;import com.artifex.mupdf.fitz.Page;import com.artifex.mupdf.fitz.StructuredText;import java.util.*;
/** Fade only native text; page images, ink, layout and the active passage stay untouched. */
final class NarrationPage {
 final ArrayList<String> words=new ArrayList<>();final ArrayList<RectF> boxes=new ArrayList<>();final float width,height;int[] aligned;NarrationIndex index;int first=-1,last=-1,maskStart=-2,maskEnd=-2;Path mask;
 NarrationPage(float width,float height){this.width=width;this.height=height;}
 static NarrationPage read(Page page){com.artifex.mupdf.fitz.Rect bounds=page.getBounds();NarrationPage data=new NarrationPage(bounds.x1-bounds.x0,bounds.y1-bounds.y0);StructuredText text=page.toStructuredText();try{for(StructuredText.TextBlock block:text.getBlocks()){if(block.lines==null)continue;for(StructuredText.TextLine line:block.lines){if(line.chars==null)continue;StringBuilder word=new StringBuilder();RectF box=null;for(StructuredText.TextChar c:line.chars){if(c.isWhitespace()){data.add(word,box);word.setLength(0);box=null;continue;}if(!Character.isValidCodePoint(c.c))continue;word.appendCodePoint(c.c);com.artifex.mupdf.fitz.Rect r=c.quad.toRect();RectF glyph=new RectF(r.x0-bounds.x0,r.y0-bounds.y0,r.x1-bounds.x0,r.y1-bounds.y0);if(box==null)box=glyph;else box.union(glyph);}data.add(word,box);}}}finally{text.destroy();}return data;}
 void add(StringBuilder value,RectF box){String word=NarrationIndex.normal(value.toString());if(!word.isEmpty()&&box!=null){words.add(word);boxes.add(box);}}
 void align(NarrationIndex index,int near){this.index=index;aligned=index.align(words,near);first=Integer.MAX_VALUE;last=-1;for(int at:aligned)if(at>=0){first=Math.min(first,index.words.get(at).start);last=Math.max(last,index.words.get(at).end);}if(last<0)first=-1;maskStart=-2;}
 void draw(Canvas canvas,RectF page,int start,int end,int paper){if(index==null||aligned==null)return;if(mask==null||maskStart!=start||maskEnd!=end){mask=new Path();for(int n=0;n<boxes.size();n++){int at=aligned[n];boolean active=at>=0&&index.words.get(at).start<end&&index.words.get(at).end>start;if(!active)mask.addRect(boxes.get(n),Path.Direction.CW);}maskStart=start;maskEnd=end;}Paint fade=new Paint();fade.setColor((paper&0x00ffffff)|0x80000000);canvas.save();canvas.clipRect(page);canvas.translate(page.left,page.top);canvas.scale(page.width()/width,page.height()/height);canvas.drawPath(mask,fade);canvas.restore();}
}
